

// ═══════════════════════════════════════════════════════════════
//  軽量Chart.js代替実装（CSP対応）
// ═══════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════
//  軽量Chart.js代替実装（CSP対応 + ツールチップ）
// ═══════════════════════════════════════════════════════════════
class SimpleChart {
  constructor(canvas, config) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d');
    this.config = config;
    this.destroyed = false;
    this.tooltip = null;
    this.hoveredPoint = null;
    
    // マウスイベント追加
    this.canvas.addEventListener('mousemove', (e) => this.handleMouseMove(e));
    this.canvas.addEventListener('mouseleave', () => this.handleMouseLeave());
    
    this.draw();
  }
  
  destroy() {
    this.destroyed = true;
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    if(this.tooltip) {
      this.tooltip.remove();
      this.tooltip = null;
    }
  }
  
  handleMouseMove(e) {
    const rect = this.canvas.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const mouseY = e.clientY - rect.top;
    
    const w = rect.width;
    const h = rect.height;
    const padding = 60;
    const plotW = w - padding * 2;
    const plotH = h - padding * 2;
    
    const opts = this.config.options;
    const datasets = this.config.data.datasets;
    
    const yMin = opts.scales.y.min || -12;
    const yMax = opts.scales.y.max || 12;
    const xMin = opts.scales.x.min || -0.5;
    const xMax = opts.scales.x.max || 0.5;
    
    const toX = (x) => padding + ((x - xMin) / (xMax - xMin)) * plotW;
    const toY = (y) => padding + plotH - ((y - yMin) / (yMax - yMin)) * plotH;
    
    // 点との距離を計算
    let closestPoint = null;
    let closestDist = Infinity;
    let closestDataset = null;
    
    datasets.forEach(ds => {
      if(ds.type === 'scatter') {
        ds.data.forEach((pt, i) => {
          const x = toX(pt.x);
          const y = toY(pt.y);
          const r = Array.isArray(ds.pointRadius) ? ds.pointRadius[i] : ds.pointRadius || 3;
          const dist = Math.sqrt((mouseX - x) ** 2 + (mouseY - y) ** 2);
          
          if(dist <= r + 5 && dist < closestDist) {
            closestDist = dist;
            closestPoint = {pt, x, y, index: i};
            closestDataset = ds;
          }
        });
      }
    });
    
    if(closestPoint) {
      this.showTooltip(closestPoint, closestDataset, e.clientX, e.clientY);
      this.canvas.style.cursor = 'pointer';
    } else {
      this.hideTooltip();
      this.canvas.style.cursor = 'default';
    }
  }
  
  handleMouseLeave() {
    this.hideTooltip();
    this.canvas.style.cursor = 'default';
  }
  
  showTooltip(point, dataset, clientX, clientY) {
    if(!this.tooltip) {
      this.tooltip = document.createElement('div');
      this.tooltip.style.position = 'fixed';
      this.tooltip.style.backgroundColor = 'rgba(26, 60, 52, 0.95)';
      this.tooltip.style.color = 'white';
      this.tooltip.style.padding = '12px';
      this.tooltip.style.borderRadius = '6px';
      this.tooltip.style.fontSize = '12px';
      this.tooltip.style.fontFamily = '"DM Sans", sans-serif';
      this.tooltip.style.pointerEvents = 'none';
      this.tooltip.style.zIndex = '10000';
      this.tooltip.style.boxShadow = '0 4px 12px rgba(0,0,0,0.3)';
      this.tooltip.style.lineHeight = '1.5';
      document.body.appendChild(this.tooltip);
    }
    
    const callbacks = this.config.options.plugins.tooltip.callbacks;
    const title = callbacks.title ? callbacks.title([{raw: point.pt}]) : '';
    const labels = callbacks.label ? callbacks.label({raw: point.pt}) : [];
    
    this.tooltip.innerHTML = `
      <div style="font-weight:600;font-size:13px;margin-bottom:6px">${title}</div>
      ${labels.map(l => `<div>${l}</div>`).join('')}
    `;
    
    this.tooltip.style.left = (clientX + 15) + 'px';
    this.tooltip.style.top = (clientY - 10) + 'px';
    this.tooltip.style.display = 'block';
  }
  
  hideTooltip() {
    if(this.tooltip) {
      this.tooltip.style.display = 'none';
    }
  }
  
  draw() {
    const rect = this.canvas.parentElement.getBoundingClientRect();
    this.canvas.width = rect.width;
    this.canvas.height = rect.height;
    
    const w = rect.width;
    const h = rect.height;
    const padding = 60;
    const plotW = w - padding * 2;
    const plotH = h - padding * 2;
    
    const ctx = this.ctx;
    const opts = this.config.options;
    const datasets = this.config.data.datasets;
    
    // 背景
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, w, h);
    
    // Y軸範囲
    const yMin = opts.scales.y.min || -12;
    const yMax = opts.scales.y.max || 12;
    const xMin = opts.scales.x.min || -0.5;
    const xMax = opts.scales.x.max || 0.5;
    
    // 座標変換
    const toX = (x) => padding + ((x - xMin) / (xMax - xMin)) * plotW;
    const toY = (y) => padding + plotH - ((y - yMin) / (yMax - yMin)) * plotH;
    
    // グリッド線
    ctx.strokeStyle = 'rgba(212, 230, 221, 0.6)';
    ctx.lineWidth = 1;
    
    for(let i = Math.ceil(yMin); i <= Math.floor(yMax); i++) {
      const y = toY(i);
      if(i === 0) {
        ctx.strokeStyle = '#2C4A40';
        ctx.lineWidth = 3;
      } else {
        ctx.strokeStyle = 'rgba(212, 230, 221, 0.6)';
        ctx.lineWidth = 1;
      }
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(w - padding, y);
      ctx.stroke();
    }
    
    // Y軸ラベル
    ctx.fillStyle = '#5A7A6E';
    ctx.font = '11px "DM Sans", sans-serif';
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    
    for(let i = Math.ceil(yMin); i <= Math.floor(yMax); i += 2) {
      const y = toY(i);
      ctx.fillText(i, padding - 10, y);
    }
    
    // X軸ラベル
    const xTickCallback = opts.scales.x.ticks.callback;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.font = '10px "DM Sans", sans-serif';
    ctx.fillStyle = '#8FAAA0';
    
    for(let i = 0; i <= Math.floor((xMax - xMin) / 2); i++) {
      const x = toX(i * 2);
      const label = xTickCallback ? xTickCallback.call({chart: this}, i * 2) : '';
      if(label) ctx.fillText(label, x, h - padding + 10);
    }
    
    // Y軸タイトル
    ctx.save();
    ctx.translate(20, h / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.font = '600 13px "DM Sans", sans-serif';
    ctx.fillStyle = '#2C4A40';
    ctx.textAlign = 'center';
    ctx.fillText(opts.scales.y.title.text || '', 0, 0);
    ctx.restore();
    
    // X軸タイトル
    if(opts.scales.x.title.display) {
      ctx.font = '11px "DM Sans", sans-serif';
      ctx.fillStyle = '#5A7A6E';
      ctx.textAlign = 'center';
      ctx.fillText(opts.scales.x.title.text || '', w / 2, h - 20);
    }
    
    // データ描画（線 → 点の順）
    datasets.forEach(ds => {
      if(ds.type === 'line') {
        // 線
        ctx.strokeStyle = ds.borderColor;
        ctx.lineWidth = ds.borderWidth || 1;
        ctx.beginPath();
        ds.data.forEach((pt, i) => {
          const x = toX(pt.x);
          const y = toY(pt.y);
          if(i === 0) ctx.moveTo(x, y);
          else ctx.lineTo(x, y);
        });
        ctx.stroke();
      }
    });
    
    datasets.forEach(ds => {
      if(ds.type === 'scatter') {
        
        // 散布点
        ds.data.forEach((pt, i) => {
          const x = toX(pt.x);
          const y = toY(pt.y);
          const r = Array.isArray(ds.pointRadius) ? ds.pointRadius[i] : ds.pointRadius || 3;
          
          const color = Array.isArray(ds.backgroundColor) ? ds.backgroundColor[i] : ds.backgroundColor;
          
          ctx.fillStyle = color;
          ctx.strokeStyle = Array.isArray(ds.borderColor) ? ds.borderColor[i] : ds.borderColor;
          ctx.lineWidth = ds.borderWidth || 1;
          
          ctx.beginPath();
          ctx.arc(x, y, r, 0, Math.PI * 2);
          ctx.fill();
          ctx.stroke();
        });
      }
    });
  }
}

// Chart.jsインターフェース互換
window.Chart = SimpleChart;


