let userLang = localStorage.getItem('metacheck_lang') || 'ja';

// 翻訳関数
function translate(key) {
  return I18N_TRANSLATIONS[userLang]?.[key] || I18N_TRANSLATIONS['ja']?.[key] || key;
}

// 翻訳を適用
function applyI18n() {
  // ログイン画面
  const loginSub = document.querySelector('.login-sub');
  if (loginSub) loginSub.textContent = translate('app_subtitle');
  
  const patientBtn = document.querySelector('.mode-btn.patient');
  const clinicBtn = document.querySelector('.mode-btn.clinic');
  if (patientBtn) patientBtn.textContent = translate('patient');
  if (clinicBtn) clinicBtn.textContent = translate('clinic');
  
  const loginBtn = document.querySelector('.login-btn');
  if (loginBtn) loginBtn.textContent = translate('login');
  
  const loginHint = document.querySelector('.login-hint');
  if (loginHint) loginHint.textContent = translate('demo_notice');
  
  // ログアウトボタン
  document.querySelectorAll('.logout-btn, .logout-btn-clinic').forEach(btn => {
    btn.textContent = translate('logout');
  });
  
  // クリニックポータル
  const clinicLabel = document.querySelector('.clinic-label');
  if (clinicLabel) clinicLabel.textContent = translate('clinic_portal');
  
  // 検索
  const searchInput = document.querySelector('input[placeholder]');
  if (searchInput && searchInput.placeholder.includes('患者')) {
    searchInput.placeholder = translate('search_placeholder');
  }
  
  // 警告メッセージ
  document.querySelectorAll('.alert, .warning').forEach(el => {
    if (el.textContent.includes('1項目で変動')) {
      el.textContent = translate('warning_message');
    }
  });
  
  // カテゴリ名の翻訳マッピング
  const categoryMap = {
    'アミノ酸・BCAA': 'amino_bcaa',
    '脂溶性・ビタミンB': 'lipid_vitamin',
    '電解質・ミネラル': 'electrolyte_mineral',
    'エネルギー産生': 'energy_production',
    '脂肪酸代謝': 'fat_acid_metabolism',
    '炭盛・メチオニン回路': 'methionine_metabolism',
    '脂肪系': 'lipid_metabolism',
    'ケトン体代謝': 'ketone_metabolism',
    '脳内伝達': 'neurotransmitter',
    'ペントースリン酸回路': 'pentose_phosphate',
    '糖盛・ゴルグタチオン': 'glucose_metabolism',
    'プリン代謝': 'purine_metabolism',
    'ビタミンB代謝': 'vitamin_b',
    '赤血球': 'carnitine_metabolism',
    'クエン酸回路': 'tca_cycle'
  };
  
  // 全テキストノードを走査してカテゴリ名を翻訳
  document.querySelectorAll('*').forEach(el => {
    if (el.children.length === 0 && el.textContent.trim()) {
      const text = el.textContent.trim();
      if (categoryMap[text]) {
        el.textContent = translate(categoryMap[text]);
      }
    }
  });
  
  // "さん"を翻訳
  document.querySelectorAll('*').forEach(el => {
    if (el.textContent.includes('さん')) {
      el.textContent = el.textContent.replace('さん', translate('patient_suffix'));
    }
  });
}

// 言語変更
function changeLanguage(lang) {
  userLang = lang;
  localStorage.setItem('metacheck_lang', lang);
  applyI18n();
  
  // ボタンの状態更新
  document.querySelectorAll('.login-lang-btn, .lang-option').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-lang') === lang);
  });
  
  // ドロップダウンの現在言語表示更新
  const langLabels = { 'ja': 'JA', 'en': 'EN', 'vi': 'VI' };
  ['patient', 'clinic'].forEach(type => {
    const textEl = document.getElementById('current-lang-text-' + type);
    if (textEl) textEl.textContent = langLabels[lang];
  });
}

// ページ読み込み時
window.addEventListener('DOMContentLoaded', () => {
  applyI18n();
  
  // 初期言語ボタンの状態
  document.querySelectorAll('.login-lang-btn, .lang-option').forEach(btn => {
    btn.classList.toggle('active', btn.getAttribute('data-lang') === userLang);
  });
  
  const langLabels = { 'ja': 'JA', 'en': 'EN', 'vi': 'VI' };
  ['patient', 'clinic'].forEach(type => {
    const textEl = document.getElementById('current-lang-text-' + type);
    if (textEl) textEl.textContent = langLabels[userLang];
  });
});

document.addEventListener('click', () => {
  document.querySelectorAll('.lang-dropdown').forEach(d => d.classList.remove('show'));
});




