function rankColor(r){
  return{A:'rank-A',B:'rank-B',C:'rank-C',D:'rank-D',E:'rank-E'}[r]||'rank-A';
}
function rankBg(r){
  return{
    A:['#D8F3DC','#2D6A4F'],B:['#E8F5E9','#3A7D44'],
    C:['#FFF9C4','#B8860B'],D:['#FFE5CC','#D4600A'],
    E:['#FDECEA','#B03A2E']
  }[r]||['#D8F3DC','#2D6A4F'];
}
function rankBarColor(r){
  return{A:'#2D6A4F',B:'#52B788',C:'#D4A017',D:'#D4600A',E:'#B03A2E'}[r]||'#2D6A4F';
}
function parseMetabolites(str){
  if(!str) return [];
  return str.split('、').map(s=>{
    const dir = s.endsWith('↓')?'down':s.endsWith('↑')?'up':'neutral';
    const name = s.replace(/[↑↓→]/g,'').trim();
    return{name,dir};
  }).filter(m=>m.name);
}
function escHtml(s){
  return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}
function formatText(s){
  return escHtml(s).replace(/\n/g,'<br>').replace(/・/g,'<br>・');
}

