// ══════════════════════════════════════════════
let currentRole = 'patient';
let currentPatientId = null;
let currentClinic = null;
let clinicSelectedPatient = null;
let clinicSelectedCat = null;
let clinicDetailTab = 'doctor';

// ══════════════════════════════════════════════
//  LOGIN
// ══════════════════════════════════════════════
function setRole(role){
  currentRole = role;
  document.getElementById('role-patient').classList.toggle('active', role==='patient');
  document.getElementById('role-clinic').classList.toggle('active', role==='clinic');
  document.getElementById('field-patient-id').style.display = role==='patient'?'block':'none';
  document.getElementById('field-clinic-id').style.display = role==='clinic'?'block':'none';
}

function doLogin(){
  const app = document.getElementById('app');
  if(currentRole==='patient'){
    const sel = document.getElementById('sel-patient-id');
    currentPatientId = sel.value;
    currentClinic = null;
    app.className = 'visible patient-only';
    showApp();
    renderPatientPanel(currentPatientId);
    renderClinicLocked();
  } else {
    const sel = document.getElementById('sel-clinic-id');
    currentClinic = sel.value;
    currentPatientId = null;
    app.className = 'visible clinic-only';
    showApp();
    renderPatientPanelEmpty();
    renderClinicPanel(currentClinic);
  }
}

function doLogout(){
  document.getElementById('login-screen').classList.remove('hidden');
  document.getElementById('app').classList.remove('visible');
  currentPatientId = null; currentClinic = null;
  clinicSelectedPatient = null;
}

function showApp(){
  document.getElementById('login-screen').classList.add('hidden');
  document.getElementById('app').classList.add('visible');
}

// ══════════════════════════════════════════════
//  PATIENT PANEL
// ══════════════════════════════════════════════
let patientRadarChart = null;

function renderPatientRadarChart(d){
  const canvas = document.getElementById('patient-radar-chart');
  if(!canvas) return;
  
  // 代表的な8カテゴリを選択
  const mainCats = [
    'Energy currency / OXPHOS',
    'TCA Cycle',
    'Glycolysis',
    'Fatty acid metabolism',
    'Ketone body metabolism',
    'Lipid detail',
    'Amino acid / BCAA metabolism',
    'Redox balance / Glutathione',
    'Folate / Methionine–SAM cycle',
    'Urea Cycle',
    'Pentose Phosphate Pathway',
    'Purine metabolism',
    'Pyrimidine metabolism',
    'Polyamine metabolism',
    'Cofactors / Vitamin B',
    'Electrolyte / Minerals'
  ];
  
  const labels = mainCats.map(c => CAT_JA[c] || c);
  const data = mainCats.map(c => {
    const cat = d.categories.find(ct => ct.category === c);
    return cat ? cat.wavg : 0;
  });
  
  // ランクに基づいた色
  const bgColors = mainCats.map(c => {
    const cat = d.categories.find(ct => ct.category === c);
    if(!cat) return 'rgba(45,106,79,0.1)';
    const [bg,] = rankBg(cat.rank);
    return bg;
  });
  
  if(patientRadarChart) patientRadarChart.destroy();
  
  patientRadarChart = new Chart(canvas, {
    type: 'radar',
    data: {
      labels: labels,
      datasets: [{
        label: '変動スコア',
        data: data,
        backgroundColor: 'rgba(45, 106, 79, 0.1)',
        borderColor: 'rgba(45, 106, 79, 0.8)',
        borderWidth: 2,
        pointBackgroundColor: bgColors,
        pointBorderColor: '#fff',
        pointBorderWidth: 2,
        pointRadius: 6,
        pointHoverRadius: 8
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        r: {
          min: 0,
          max: 1.2,
          ticks: {
            stepSize: 0.2,
            font: { size: 10, family: 'DM Sans' },
            color: '#8FAAA0'
          },
          grid: {
            color: 'rgba(212, 230, 221, 0.5)'
          },
          pointLabels: {
            font: { size: 11, family: 'DM Sans', weight: '500' },
            color: '#2C4A40'
          }
        }
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: 'rgba(26, 60, 52, 0.95)',
          titleFont: { size: 12, family: 'DM Sans', weight: '600' },
          bodyFont: { size: 11, family: 'DM Sans' },
          padding: 10,
          borderColor: 'rgba(82, 183, 136, 0.3)',
          borderWidth: 1,
          callbacks: {
            label: function(context) {
              const cat = mainCats[context.dataIndex];
              const detail = d.categories.find(c => c.category === cat);
              return [
                `変動スコア: ${context.parsed.r.toFixed(3)}`,
                detail ? `ランク: ${detail.rank}` : ''
              ].filter(Boolean);
            }
          }
        }
      }
    }
  });
}

