function renderPatientPanel(pid){
  const d = PATIENT_DATA[pid];
  if(!d) return;
  document.getElementById('pt-topbar-id').textContent = pid;
  document.getElementById('pt-avatar').textContent = pid.slice(-3);

  // Count ranks
  const rankCount = {A:0,B:0,C:0,D:0,E:0};
  d.categories.forEach(c=>{ if(rankCount[c.rank]!==undefined) rankCount[c.rank]++; });
  const worstCats = d.categories.filter(c=>c.rank==='E'||c.rank==='D');
  const firstCat = d.categories[0];
  const selectedCat = d.categories.find(c=>c.rank==='E')||d.categories.find(c=>c.rank==='D')||firstCat;

  document.getElementById('patient-content').innerHTML = `
    <div class="pt-header fade-up">
      <div class="pt-id">患者ID: ${pid}</div>
      <div class="pt-name">${pid} さん</div>
      <div class="pt-meta">
        <span>📅 測定日 ${d.date||'—'}</span>
        <span>🌏 ${d.country||'—'}</span>
      </div>
    </div>

    ${worstCats.length>0?`<div class="notice">⚠️ ${worstCats.length}項目で変動が大きく検出されました。詳細はクリニックにご相談ください。</div>`:''}

    

    <div class="section-title">代謝スコア一覧</div>
    <div class="score-grid fade-up" id="pt-score-grid"></div>

    <div class="section-title">選択カテゴリの説明</div>
    <div id="pt-detail-area"></div>

    <div class="pt-cta fade-up">
      <div class="pt-cta-icon">💬</div>
      <div class="pt-cta-text">
        <strong>クリニックへご相談ください</strong>
        この結果は参考情報です。診断・治療は必ず医師の指示に従ってください。
      </div>
    </div>
  `;

  renderPatientScoreGrid(d, selectedCat.category);
  renderPatientDetail(d, selectedCat.category);
  
}

function renderPatientScoreGrid(d, activeCat){
  const grid = document.getElementById('pt-score-grid');
  if(!grid) return;
  grid.innerHTML = d.categories.map(c=>{
    const [bg,fg] = rankBg(c.rank);
    const barW = Math.min(100, c.wavg * 80);
    const barC = rankBarColor(c.rank);
    return `
    <div class="score-card ${c.category===activeCat?'active':''} fade-up"
         onclick="renderPatientDetail(currentPatientData,'${c.category.replace(/'/g,"\\'")}');highlightScoreCard('${c.category.replace(/'/g,"\\'")}')">
      <div class="score-card-rank rank-badge ${rankColor(c.rank)}">${c.rank}</div>
      <div class="score-card-name">${CAT_ICONS[c.category]||'🔬'} ${CAT_JA[c.category]||c.category}</div>
      <div class="score-bar-wrap"><div class="score-bar" style="width:${barW}%;background:${barC}"></div></div>
    </div>`;
  }).join('');
}

function highlightScoreCard(cat){
  document.querySelectorAll('#pt-score-grid .score-card').forEach(el=>{
    el.classList.remove('active');
  });
  event.currentTarget.classList.add('active');
}

let currentPatientData = null;
function renderPatientDetail(d, catName){
  if(typeof d === 'string'){ d = PATIENT_DATA[d]; }
  currentPatientData = d;
  const cat = d.categories.find(c=>c.category===catName);
  if(!cat) return;
  const area = document.getElementById('pt-detail-area');
  if(!area) return;
  
  // カテゴリ説明を取得
  const catDesc = CATEGORY_DESCRIPTIONS[catName];
  const descHtml = catDesc ? `<p style="margin:8px 0 12px 0;padding:0 8px;font-size:12px;line-height:1.5;color:#666">${catDesc.description}</p>` : '';
  
  const mets = parseMetabolites(cat.metabolites);
  const metHtml = mets.map(m=>{
    const desc = METABOLITE_DESCRIPTIONS ? (METABOLITE_DESCRIPTIONS[m.name] || '') : '';
    const arrow = m.dir==='down'?'↓':m.dir==='up'?'↑':'';
    return `<span class="metabolite-tag ${m.dir}" title="${desc}" style="cursor:${desc?'help':'default'};${desc?'border-bottom:1px dotted #666':''}">${m.name}${arrow}</span>`;
  }).join('');
  
  area.innerHTML = `
    <div class="pt-detail fade-up">
      <div class="pt-detail-title">
        <div class="pt-detail-rank rank-badge ${rankColor(cat.rank)}">${cat.rank}</div>
        ${CAT_ICONS[cat.category]||''} ${CAT_JA[cat.category]||cat.category}
      </div>
      ${descHtml}
      
      <div style="margin:12px 0;padding:12px;background:var(--foam);border-radius:8px">
        <div style="font-size:11px;color:var(--ink3);margin-bottom:6px">主要な変動</div>
        <div class="metabolite-list">${metHtml}</div>
      </div>
      
      <div class="detail-tabs" style="margin-bottom:16px">
        <div class="detail-tab active" onclick="switchPatientDetailTab('metabolites',this,'${d.id||currentPatientId}','${catName.replace(/'/g,"\\'")}')">🧪 個別代謝物</div>
        <div class="detail-tab" onclick="switchPatientDetailTab('patient',this,'${d.id||currentPatientId}','${catName.replace(/'/g,"\\'")}')">💬 生活で気をつけること</div>
      </div>
      
      <div id="patient-detail-tab-body"></div>
    </div>`;
    
  // デフォルトで個別代謝物タブを表示
  setTimeout(() => {
    const tabs = area.querySelectorAll('.detail-tab');
    tabs.forEach(tab => {
      tab.addEventListener('click', function() {
        const tabType = this.getAttribute('data-tab');
        switchPatientDetailTab(tabType, this, d.id || currentPatientId, catName);
      });
    });
    // 初期表示
    if(tabs[0]) switchPatientDetailTab('metabolites', tabs[0], d.id || currentPatientId, catName);
  }, 50);
}

function switchPatientDetailTab(tab, el, pid, catName){
  console.log('=== switchPatientDetailTab called ===');
  console.log('tab:', tab);
  console.log('pid:', pid);
  console.log('catName:', catName);
  
  document.querySelectorAll('.detail-tab').forEach(t => t.classList.remove('active'));
  el.classList.add('active');
  
  const patient = typeof pid === 'string' ? PATIENT_DATA[pid] : currentPatientData;
  console.log('patient:', patient);
  const cat = patient.categories.find(c => c.category === catName);
  if(!cat) return;
  
  const body = document.getElementById('patient-detail-tab-body');
  if(!body) return;
  
  if(tab === 'metabolites'){
    // 個別代謝物タブ
    const measurements = patient.measurements || [{date: patient.date, categories: patient.categories}];
    const allMeasurementData = measurements.map((m, mIdx) => {
      const metData = METABOLITE_DATA?.[pid]?.[catName] || [];
      console.log('測定', mIdx, ':', metData.length, 'metabolites');
      return { date: m.date, index: mIdx, metData: metData };
    });
    console.log('allMeasurementData:', allMeasurementData);
    
    const latestMetData = allMeasurementData[0]?.metData || [];
    
    if(latestMetData.length === 0){
      body.innerHTML = '<p style="text-align:center;color:var(--ink4);padding:40px">このカテゴリの詳細データがありません</p>';
      return;
    }
    
    const sortedMets = [...latestMetData].sort((a,b) => {
      const scoreA = (a.weight || 0) * Math.abs(a.log2fc || 0);
      const scoreB = (b.weight || 0) * Math.abs(b.log2fc || 0);
      return scoreB - scoreA;
    });
    
    body.innerHTML = `
      <div style="height:350px;position:relative;margin-bottom:16px">
        <canvas id="metabolite-scatter-chart"></canvas>
      </div>
      <div style="max-height:400px;overflow-y:auto">
        ${renderMetaboliteTableMulti(sortedMets, measurements)}
      </div>
    `;
    
    setTimeout(() => drawMetaboliteScatterMulti(allMeasurementData, catName), 50);
    
  } else if(tab === 'patient'){
    // 患者向けコメントタブ
    body.innerHTML = `
      <div style="overflow-x:auto">
        <table class="score-table" style="table-layout:fixed;width:100%">
          <thead>
            <tr>
              <th style="width:35%">変動について</th>
              <th style="width:65%">生活で気をつけること</th>
            </tr>
          </thead>
          <tbody>
            ${(cat.metabolite_insights || []).map(insight => `
              <tr style="vertical-align:top">
                <td style="padding:12px;line-height:1.6;background:rgba(33,150,243,0.05)">
                  ${insight.movement}
                </td>
                <td style="padding:12px;line-height:1.6;background:rgba(46,125,50,0.05)">
                  ${insight.patient_comment}
                </td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;
  }
}

// ══════════════════════════════════════════════
//  CLINIC PANEL
// ══════════════════════════════════════════════
function renderClinicPanel(clinic){
  const clinicName = {AA:'クリニックA',AB:'クリニックB',AC:'クリニックC',AD:'クリニックD'}[clinic]||clinic;
  document.getElementById('cl-topbar-name').textContent = clinicName;
  document.getElementById('cl-avatar').textContent = clinic;

  // Get patients for this clinic
  const patients = Object.entries(PATIENT_DATA)
    .filter(([pid,d])=>d.clinic===clinic)
    .map(([pid,d])=>({pid,data:d}));

  const container = document.getElementById('clinic-content');
  container.innerHTML = `
    <div class="clinic-sidebar" id="clinic-sidebar">
      <div class="sidebar-search">
        <input type="text" placeholder="患者IDで検索..." id="patient-search" oninput="filterPatients('${clinic}',this.value)">
      </div>
      <div class="sidebar-list" id="patient-list"></div>
    </div>
    <div class="clinic-main">
      <div class="clinic-main-scroll" id="clinic-main-scroll">
        <div class="empty-state" style="height:400px">
          <div class="empty-icon">👈</div>
          <div class="empty-title">患者を選択してください</div>
          <div class="empty-sub">${clinicName}の患者 ${patients.length}名が登録されています</div>
        </div>
      </div>
    </div>`;

  renderPatientList(clinic, '');

  // auto-select first
  if(patients.length>0){
    setTimeout(()=>selectClinicPatient(patients[0].pid), 100);
  }
}

function filterPatients(clinic, q){
  renderPatientList(clinic, q);
}

function renderPatientList(clinic, q){
  const patients = Object.entries(PATIENT_DATA)
    .filter(([pid,d])=>d.clinic===clinic && pid.toLowerCase().includes(q.toLowerCase()))
    .map(([pid,d])=>({pid,data:d}));

  const list = document.getElementById('patient-list');
  if(!list) return;
  list.innerHTML = patients.map(({pid,data})=>{
    const rankDots = ''; // ランクバッジを削除
    return `
    <div class="patient-item ${clinicSelectedPatient===pid?'active':''}" onclick="selectClinicPatient('${pid}')">
      <div class="pi-dot">${pid.slice(-3)}</div>
      <div class="pi-info">
        <div class="pi-id">${pid}</div>
        <div class="pi-meta">${data.date||'—'} / ${data.sex||'—'} / ${data.country||'—'}</div>
        
      </div>
    </div>`;
  }).join('');
}

function selectClinicPatient(pid){
  clinicSelectedPatient = pid;
  clinicSelectedCat = null;
  clinicDetailTab = 'doctor';
  selectedMeasurementIndex = 0;
  compareMeasurementIndex = null;

  // Re-render list to show active
  if(currentClinic) renderPatientList(currentClinic, document.getElementById('patient-search')?.value||'');

  const d = PATIENT_DATA[pid];
  if(!d) return;

  const measurements = d.measurements || [{date: d.date, categories: d.categories}];
  const currentMeasurement = measurements[selectedMeasurementIndex];

  const rankCount = {A:0,B:0,C:0,D:0,E:0};
  currentMeasurement.categories.forEach(c=>{ if(rankCount[c.rank]!==undefined) rankCount[c.rank]++; });
  const worst = currentMeasurement.categories.reduce((a,b)=>{
    const order = {E:4,D:3,C:2,B:1,A:0};
    return (order[a.rank]||0)>=(order[b.rank]||0)?a:b;
  });

  const scroll = document.getElementById('clinic-main-scroll');
  if(!scroll) return;
  
  // 時系列セレクタ
  const tsSelector = measurements.length > 1 ? `
    <div class="timeseries-selector fade-up">
      <div class="ts-label">📅 測定履歴</div>
      ${measurements.map((m, i) => `
        <button class="ts-date-btn ${i === selectedMeasurementIndex ? 'active' : ''}" 
                onclick="selectMeasurement('${pid}', ${i})">${m.date}</button>
      `).join('')}
      ${measurements.length > 1 ? `
        <div style="flex:1"></div>
        <div class="ts-label" style="color:var(--amber)">比較</div>
        ${measurements.map((m, i) => `
          <button class="ts-date-btn compare ${i === compareMeasurementIndex ? 'active' : ''}" 
                  onclick="toggleCompare('${pid}', ${i})">${m.date}</button>
        `).join('')}
      ` : ''}
    </div>
  ` : '';

  scroll.innerHTML = `
    <div class="clinic-pt-header fade-up">
      <div class="cph-left">
        <div class="cph-id">${pid}</div>
        <div class="cph-name">患者 ${pid.slice(-3)}</div>
        <div class="cph-meta">
          <span class="cph-badge">📅 ${currentMeasurement.date||'—'}</span>
          <span class="cph-badge">⚧ ${d.sex||'—'}</span>
          <span class="cph-badge">🌏 ${d.country||'—'}</span>
          <span class="cph-badge">${d.clinic_name||''}</span>
          ${measurements.length > 1 ? `<span class="cph-badge" style="background:var(--sage);color:#fff">測定${measurements.length}回</span>` : ''}
        </div>
      </div>
      <div class="cph-right">
        <button class="action-btn secondary" onclick="exportPDF('${pid}')">📄 PDF出力</button>
        <button class="action-btn primary" onclick="saveMemo('${pid}')">💾 メモ保存</button>
      </div>
    </div>

    ${tsSelector}

    ${compareMeasurementIndex !== null ? renderComparison(pid, selectedMeasurementIndex, compareMeasurementIndex) : ''}

    <div class="memo-box fade-up">
      <div class="memo-title">📝 診察メモ・カルテ記入</div>
      <textarea class="memo-textarea" id="memo-${pid}" placeholder="医師向けメモ・カルテ内容をここに記入してください..." oninput="markMemoUnsaved('${pid}')">${getMemo(pid)}</textarea>
      <div class="memo-saved" id="memo-saved-${pid}">✓ 保存しました</div>
    </div>

    

    

    

    <div class="section-title">全カテゴリ 代謝変動の推移</div>
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:20px" class="fade-up" id="category-scatter-grid"></div>

    <div class="section-title">📊 カテゴリ選択</div>
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:24px" class="fade-up" id="category-button-grid"></div>

    <div class="section-title" id="detail-section-title" style="display:none">📋 カテゴリ詳細</div>
    <div id="clinic-cat-detail" style="margin-bottom:30px"></div>

    
  `;

  
  renderCategoryButtons(pid, d.categories);
  
  
  
  // auto-select worst category
  selectClinicCategory(pid, worst.category);
}

function renderClinicScoreTable(d){
  const tbody = document.getElementById('clinic-score-tbody');
  if(!tbody) return;
  tbody.innerHTML = d.categories.map(c=>{
    const measurements = d.measurements || [{categories: d.categories}];
    const isMulti = measurements.length > 1;
    
    // 最新と最古の測定でスコア変化を計算
    let changeHtml = '<td>—</td>';
    if(isMulti){
      const oldCat = measurements[0].categories.find(ct => ct.category === c.category);
      const newCat = measurements[measurements.length - 1].categories.find(ct => ct.category === c.category);
      if(oldCat && newCat){
        const change = newCat.wavg - oldCat.wavg;
        const changePercent = ((change / oldCat.wavg) * 100).toFixed(1);
        const arrow = change > 0.05 ? '↑' : change < -0.05 ? '↓' : '→';
        const color = change > 0.05 ? '#B03A2E' : change < -0.05 ? '#2E7D32' : 'var(--ink4)';
        changeHtml = `<td style="color:${color};font-weight:600">${arrow} ${changePercent}%</td>`;
      }
    }
    
    const barW = Math.min(100, c.wavg * 80);
    const barC = rankBarColor(c.rank);
    const mets = parseMetabolites(c.metabolites).slice(0,3);
    const metHtml = mets.map(m=>{
    const desc = METABOLITE_DESCRIPTIONS ? (METABOLITE_DESCRIPTIONS[m.name] || '') : '';
    const arrow = m.dir==='down'?'↓':m.dir==='up'?'↑':'';
    return `<span class="metabolite-tag ${m.dir}" title="${desc}" style="cursor:${desc?'help':'default'};${desc?'border-bottom:1px dotted #666':''}">${m.name}${arrow}</span>`;
  }).join('');
    return `
    <tr onclick="selectClinicCategory('${clinicSelectedPatient}','${c.category.replace(/'/g,"\\'")}')">
      <td><strong>${CAT_ICONS[c.category]||''} ${CAT_JA[c.category]||c.category}</strong><br><span style="font-size:10px;color:var(--ink4)">${c.category}</span></td>
      <td><span class="rank-badge ${rankColor(c.rank)}">${c.rank}</span></td>
      <td>
        <div class="wavg-bar-wrap">
          <div class="wavg-bar-bg"><div class="wavg-bar-fill" style="width:${barW}%;background:${barC}"></div></div>
          <div class="wavg-num">${c.wavg.toFixed(3)}</div>
        </div>
      </td>
      <td><div class="metabolite-list">${metHtml}</div></td>
    </tr>`;
  }).join('');
}

function selectClinicCategory(pid, catName){
  clinicSelectedCat = catName;
  const d = PATIENT_DATA[pid];
  if(!d) return;
  const cat = d.categories.find(c=>c.category===catName);
  if(!cat) return;

  // highlight row
  document.querySelectorAll('#clinic-score-tbody tr').forEach((tr,i)=>{
    tr.classList.toggle('active', d.categories[i]?.category===catName);
  });

  const titleEl = document.getElementById('detail-section-title');
  if(titleEl) titleEl.style.display='block';

  const mets = parseMetabolites(cat.metabolites);
  const metHtml = mets.map(m=>{
    const desc = METABOLITE_DESCRIPTIONS ? (METABOLITE_DESCRIPTIONS[m.name] || '') : '';
    const arrow = m.dir==='down'?'↓':m.dir==='up'?'↑':'';
    return `<span class="metabolite-tag ${m.dir}" title="${desc}" style="cursor:${desc?'help':'default'};${desc?'border-bottom:1px dotted #666':''}">${m.name}${arrow}</span>`;
  }).join('');

  const detailEl = document.getElementById('clinic-cat-detail');
  if(!detailEl) return;

  const catDesc = CATEGORY_DESCRIPTIONS[catName];
  const descHtml = catDesc ? `<p style="margin:4px 0 16px 0;font-size:12px;line-height:1.5;color:#666">${catDesc.description}</p>` : '';
  
  detailEl.innerHTML = `
    <div class="fade-up">
      <h3 style="margin:0 0 4px 0;font-size:18px;color:#2C4A40">${CAT_JA[catName] || catName}</h3>
      ${descHtml}
      <div style="margin-bottom:20px" class="fade-up">
        <div class="cdp-box" style="width:100%">
          <div class="cdp-title"><div class="cdp-title-icon">⚗️</div>主要変動代謝物</div>
          <div class="metabolite-list" style="font-size:14px;line-height:1.8">${metHtml||'<span style="color:var(--ink4);font-size:13px">データなし</span>'}</div>
        </div>
        
      </div>
      <div class="detail-tabs">
        <div class="detail-tab active" onclick="switchDetailTab('metabolites',this,'${pid}','${catName.replace(/'/g,"\\'")}')">🧪 個別代謝物</div>
        <div class="detail-tab" onclick="switchDetailTab('clinical',this,'${pid}','${catName.replace(/'/g,"\\'")}')">🔬 臨床解釈・介入</div>
        <div class="detail-tab" onclick="switchDetailTab('patient',this,'${pid}','${catName.replace(/'/g,"\\'")}')">💬 患者向けコメント</div>
      </div>
      <div id="clinic-detail-body" style="margin-top:16px">
          <div class="cdp-title"><div class="cdp-title-icon">🩺</div>医師向け評価</div>
          <div class="cdp-body">${formatText(cat.doctor_eval)}</div>
        </div>
      </div>
    </div>`;
  
  
  
  // 個別代謝物タブをアクティブ化して表示
  clinicDetailTab = 'metabolites';
  setTimeout(() => {
    const tabs = document.querySelectorAll('.detail-tab');
    tabs.forEach(t => t.classList.remove('active'));
    const metabolitesTab = Array.from(tabs).find(t => t.textContent.includes('個別代謝物'));
    if(metabolitesTab){
      metabolitesTab.classList.add('active');
      switchDetailTab('metabolites', metabolitesTab, pid, catName);
    }
  }, 100);
  
  // デフォルトで個別代謝物タブを開く
  setTimeout(() => {
    const firstTab = document.querySelector('.detail-tab');
    if(firstTab) switchDetailTab('metabolites', firstTab, pid, catName);
  }, 50);
}

function switchDetailTab(tab, el, pid, catName){
  document.querySelectorAll('.detail-tab').forEach(t=>t.classList.remove('active'));
  el.classList.add('active');

  const d = PATIENT_DATA[pid];
  const cat = d?.categories.find(c=>c.category===catName);
  if(!cat) return;

  const titles = {
    metabolites:['🧪','個別代謝物データ','metabolites'],
    clinical:['🔬','臨床解釈・介入（医師専用）','clinical'],
    patient:['💬','患者向けコメント','patient']
  };
  const [icon,title,key] = titles[tab]||titles.metabolites;
  const body = document.getElementById('clinic-detail-body');
  
    if(tab === 'metabolites'){
    // 代謝物タブ：カテゴリごとの散布図 + テーブル（複数測定対応）
    if(!body) return;
    
    const d = PATIENT_DATA[pid];
    const measurements = d.measurements || [{date: d.date, categories: d.categories}];
    
    // 各測定ごとに、このカテゴリのデータを取得
    const allMeasurementData = measurements.map((m, mIdx) => {
      const cat = m.categories.find(c => c.category === catName);
      const metData = METABOLITE_DATA?.[pid]?.[catName] || [];
      return {
        date: m.date,
        index: mIdx,
        metData: metData
      };
    });
    
    // 最新測定のデータでテーブル表示
    const latestMetData = allMeasurementData[selectedMeasurementIndex]?.metData || [];
    
    if(latestMetData.length === 0){
      body.innerHTML = `
        <div class="cdp-title"><div class="cdp-title-icon">${icon}</div>${title}</div>
        <div class="cdp-body" style="text-align:center;padding:40px;color:var(--ink4)">このカテゴリの個別代謝物データがありません</div>`;
      return;
    }
    
    // デフォルトソート：Weight × abs(log2FC) の降順
    const sortedMets = [...latestMetData].sort((a,b) => {
      const scoreA = (a.weight || 0) * Math.abs(a.log2fc || 0);
      const scoreB = (b.weight || 0) * Math.abs(b.log2fc || 0);
      return scoreB - scoreA;
    });
    
    body.innerHTML = `
      <div class="cdp-title"><div class="cdp-title-icon">${icon}</div>${title}</div>
      <div style="margin-bottom:16px">
        <div style="font-size:11px;color:var(--ink3);margin-bottom:8px">
          縦軸=乖離度。。${measurements.length > 1 ? '複数測定は横に並んで表示されます。' : ''}
        </div>
        <div style="height:450px;position:relative">
          <canvas id="metabolite-scatter-chart"></canvas>
        </div>
      </div>
      <div style="margin-bottom:8px;display:flex;gap:8px;align-items:center">
        <span style="font-size:11px;color:var(--ink3);font-weight:600">並び替え:</span>
        <button onclick="sortMetabolites('${pid}','${catName.replace(/'/g,"\'")}','weight')" 
                class="ts-date-btn" style="font-size:11px;padding:4px 10px">影響度順</button>
        <button onclick="sortMetabolites('${pid}','${catName.replace(/'/g,"\'")}','abs_log2fc')" 
                class="ts-date-btn" style="font-size:11px;padding:4px 10px">変動大きい順</button>
        <button onclick="sortMetabolites('${pid}','${catName.replace(/'/g,"\'")}','log2fc_asc')" 
                class="ts-date-btn" style="font-size:11px;padding:4px 10px">低い順</button>
        <button onclick="sortMetabolites('${pid}','${catName.replace(/'/g,"\'")}','log2fc_desc')" 
                class="ts-date-btn" style="font-size:11px;padding:4px 10px">高い順</button>
      </div>
      <div style="max-height:400px;overflow-y:auto" id="metabolite-table-container">
        ${renderMetaboliteTableMulti(sortedMets, measurements)}
      </div>`;
    
    // 散布図描画（全測定分）
    setTimeout(() => drawMetaboliteScatterMulti(allMeasurementData, catName), 50);
    
  } else if(tab === 'clinical'){
    // 臨床解釈・介入タブ：表形式で横並び
    if(!body) return;
    
    const clinical = cat.clinical_interp || 'データなし';
    const logic = cat.logic || '';
    const intervention = cat.intervention || '';
    const recommendation = cat.recommendation || '';
    
    body.innerHTML = `
      <div class="cdp-title"><div class="cdp-title-icon">${icon}</div>${title}</div>
      <div style="overflow-x:auto;margin-bottom:20px">
        <table class="score-table" style="table-layout:fixed;width:100%">
          <thead>
            <tr>
              <th style="width:25%">カテゴリ</th>
              <th style="width:30%">代謝の動き</th>
              <th style="width:25%">臨床的解釈</th>
              <th style="width:25%">推奨対策</th>
              
            </tr>
          </thead>
          <tbody>
            ${(cat.metabolite_insights || []).map((insight, idx) => `
              <tr style="vertical-align:top">
                ${idx === 0 ? `<td rowspan="${cat.metabolite_insights.length}" style="padding:12px;line-height:1.6;background:var(--sage);border-right:2px solid var(--emerald);font-weight:600;color:var(--forest);vertical-align:middle;text-align:center">
                  ${CATEGORY_INFO[catName]?.ja_name || CAT_JA[catName] || catName}
                </td>` : ''}
                <td style="padding:12px;line-height:1.6;background:rgba(33,150,243,0.05);border-left:3px solid #2196F3">
                  ${insight.movement}
                </td>
                <td style="padding:12px;line-height:1.6">
                  ${insight.interpretation}
                </td>
                <td style="padding:12px;line-height:1.6;background:var(--foam)">
                  ${insight.recommendation}
                </td>
                
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;
  } else if(tab === 'patient'){
    // 患者向けコメントタブ
    if(!body) return;
    
    body.innerHTML = `
      <div class="cdp-title"><div class="cdp-title-icon">${icon}</div>${title}</div>
      <div style="overflow-x:auto;margin-bottom:20px">
        <table class="score-table" style="table-layout:fixed;width:100%">
          <thead>
            <tr>
              <th style="width:25%">カテゴリ</th>
              <th style="width:30%">変動について</th>
              <th style="width:50%">生活で心がけること</th>
            </tr>
          </thead>
          <tbody>
            ${(cat.metabolite_insights || []).map((insight, idx) => `
              <tr style="vertical-align:top">
                ${idx === 0 ? `<td rowspan="${cat.metabolite_insights.length}" style="padding:12px;line-height:1.6;background:var(--sage);border-right:2px solid var(--emerald);font-weight:600;color:var(--forest);vertical-align:middle;text-align:center">
                  ${CATEGORY_INFO[catName]?.ja_name || CAT_JA[catName] || catName}
                </td>` : ''}
                <td style="padding:12px;line-height:1.6;background:rgba(33,150,243,0.05)">
                  ${insight.movement}
                </td>
                <td style="padding:12px;line-height:1.6;background:rgba(46,125,50,0.05)">
                  ${insight.patient_comment}
                </td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;
  } else {
    // その他のタブ
    if(body) body.innerHTML = `
      <div class="cdp-title"><div class="cdp-title-icon">${icon}</div>${title}</div>
      <div class="cdp-body">${formatText(cat[key])}</div>`;
  }
}

let metaboliteScatterChart = null;
function drawMetaboliteScatter(data, catName){
  const canvas = document.getElementById('metabolite-scatter-chart');
  if(!canvas) return;
  
  if(metaboliteScatterChart) metaboliteScatterChart.destroy();
  
  // 色分け：log2FC > 0 = 赤、< 0 = 青
  // サイズ：Weightに応じて変化
  const colors = data.map(d => d.y > 0 ? 'rgba(176, 58, 46, 0.7)' : 'rgba(46, 125, 50, 0.7)');
  const radii = data.map(d => 4 + (d.weight || 0) * 2.5);
  
  // 横にランダムにばらつかせて重ならないようにする
  const dataWithJitter = data.map(d => ({
    ...d,
    x: (Math.random() - 0.5) * 0.3 // -0.15 〜 0.15 の範囲でランダム
  }));
  
  metaboliteScatterChart = new Chart(canvas, {
    type: 'scatter',
    data: {
      datasets: [{
        label: CAT_JA[catName] || catName,
        data: dataWithJitter,
        backgroundColor: colors,
        borderColor: colors.map(c => c.replace('0.7', '1')),
        borderWidth: 1,
        pointRadius: 2,
        pointHoverRadius: radii.map(r => r + 2)
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        y: {
          title: {
            display: true,
            text: 'log2 Fold Change（高い / 低い）',
            font: { size: 12, family: 'DM Sans', weight: '600' },
            color: '#2C4A40'
          },
          ticks: {
            font: { size: 11, family: 'DM Sans' },
            color: '#5A7A6E'
          },
          grid: { 
            color: (ctx) => ctx.tick.value === 0 ? '#2C4A40' : 'rgba(212, 230, 221, 0.6)',
            lineWidth: (ctx) => ctx.tick.value === 0 ? 2 : 1
          }
        },
        x: {
          title: {
            display: true,
            text: '測定回（今後複数測定時に横に並ぶ）',
            font: { size: 11, family: 'DM Sans' },
            color: '#8FAAA0'
          },
          min: -1,
          max: 1,
          ticks: {
            display: false
          },
          grid: { 
            color: 'rgba(212, 230, 221, 0.3)',
            drawTicks: false
          }
        }
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: 'rgba(26, 60, 52, 0.95)',
          titleFont: { size: 13, family: 'DM Sans', weight: '600' },
          bodyFont: { size: 12, family: 'DM Sans' },
          padding: 12,
          callbacks: {
            title: (ctx) => ctx[0].raw.compound,
            label: (ctx) => [
              `乖離度: ${ctx.raw.y.toFixed(3)} ${ctx.raw.y > 0 ? '↑' : '↓'}`,
              `実測値: ${ctx.raw.sample.toFixed(2)}`,
              `基準値: ${ctx.raw.baseline.toFixed(2)}`,
              `Weight: ${ctx.raw.weight.toFixed(1)} （影響度${ctx.raw.weight > 2 ? '大' : ctx.raw.weight > 1 ? '中' : '小'}）`
            ]
          }
        }
      }
    }
  });
}

// ══════════════════════════════════════════════
//  TIMESERIES FUNCTIONS
// ══════════════════════════════════════════════
function selectMeasurement(pid, index){
  selectedMeasurementIndex = index;
  compareMeasurementIndex = null;
  selectClinicPatient(pid);
}

function toggleCompare(pid, index){
  if(index === selectedMeasurementIndex){
    alert('同じ測定を比較することはできません');
    return;
  }
  compareMeasurementIndex = (compareMeasurementIndex === index) ? null : index;
  selectClinicPatient(pid);
}

function renderComparison(pid, idx1, idx2){
  const d = PATIENT_DATA[pid];
  const m1 = d.measurements[idx1];
  const m2 = d.measurements[idx2];
  
  const html = `
    <div class="comparison-grid fade-up">
      <div class="comparison-card primary">
        <div class="comp-header">
          <div class="comp-date">📅 ${m1.date}<span class="comp-badge primary">基準</span></div>
        </div>
        <div class="comp-score-mini">
          ${m1.categories.slice(0, 8).map(c => `
            <div class="comp-score-row">
              <div class="comp-score-label">${CAT_JA[c.category]||c.category}</div>
              <div class="comp-score-rank rank-badge ${rankColor(c.rank)}">${c.rank}</div>
              <div class="comp-score-val">${c.wavg.toFixed(3)}</div>
              <div class="comp-score-change">—</div>
            </div>
          `).join('')}
        </div>
      </div>
      <div class="comparison-card secondary">
        <div class="comp-header">
          <div class="comp-date">📅 ${m2.date}<span class="comp-badge secondary">比較</span></div>
        </div>
        <div class="comp-score-mini">
          ${m2.categories.slice(0, 8).map((c, i) => {
            const baseline = m1.categories[i];
            const diff = c.wavg - baseline.wavg;
            const diffClass = diff > 0.05 ? 'up' : diff < -0.05 ? 'down' : 'neutral';
            const diffText = diff > 0.05 ? `+${(diff*100).toFixed(0)}%` : diff < -0.05 ? `${(diff*100).toFixed(0)}%` : '—';
            return `
            <div class="comp-score-row">
              <div class="comp-score-label">${CAT_JA[c.category]||c.category}</div>
              <div class="comp-score-rank rank-badge ${rankColor(c.rank)}">${c.rank}</div>
              <div class="comp-score-val">${c.wavg.toFixed(3)}</div>
              <div class="comp-score-change ${diffClass}">${diffText}</div>
            </div>`;
          }).join('')}
        </div>
      </div>
    </div>
  `;
  return html;
}





// ══════════════════════════════════════════════
//  MEMO & PDF
// ══════════════════════════════════════════════
function getMemo(pid){
  return localStorage.getItem(`metacheck_memo_${pid}`) || '';
}

function saveMemo(pid){
  const textarea = document.getElementById(`memo-${pid}`);
  if(!textarea) return;
  localStorage.setItem(`metacheck_memo_${pid}`, textarea.value);
  const saved = document.getElementById(`memo-saved-${pid}`);
  if(saved){
    saved.classList.add('show');
    setTimeout(()=> saved.classList.remove('show'), 2000);
  }
}

function markMemoUnsaved(pid){
  const saved = document.getElementById(`memo-saved-${pid}`);
  if(saved) saved.classList.remove('show');
}

function exportPDF(pid){
  // シンプルなブラウザ印刷ダイアログを開く
  window.print();
}

