// ══════════════════════════════════════════════
let clinicRadarChart = null;

function renderClinicRadarChart(d){
  const canvas = document.getElementById('clinic-radar-chart');
  if(!canvas) return;
  
  const mainCats = [
    'Energy currency / OXPHOS',
    'TCA Cycle',
    'Glycolysis',
    'Fatty acid metabolism',
    'Ketone body metabolism',
    'Lipid detail',
    'Amino acid / BCAA metabolism',
    'Redox balance / Glutathione',
    'Folate / Methionine–SAM cycle',
    'Urea Cycle',
    'Pentose Phosphate Pathway',
    'Purine metabolism',
    'Pyrimidine metabolism',
    'Polyamine metabolism',
    'Cofactors / Vitamin B',
    'Electrolyte / Minerals'
  ];
  
  const labels = mainCats.map(c => CAT_JA[c] || c);
  const data = mainCats.map(c => {
    const cat = d.categories.find(ct => ct.category === c);
    return cat ? cat.wavg : 0;
  });
  
  const bgColors = mainCats.map(c => {
    const cat = d.categories.find(ct => ct.category === c);
    if(!cat) return 'rgba(45,106,79,0.1)';
    const [bg,] = rankBg(cat.rank);
    return bg;
  });
  
  if(clinicRadarChart) clinicRadarChart.destroy();
  
  clinicRadarChart = new Chart(canvas, {
    type: 'radar',
    data: {
      labels: labels,
      datasets: [{
        label: 'WAVG変動スコア',
        data: data,
        backgroundColor: 'rgba(45, 106, 79, 0.15)',
        borderColor: 'rgba(45, 106, 79, 0.9)',
        borderWidth: 2,
        pointBackgroundColor: bgColors,
        pointBorderColor: '#fff',
        pointBorderWidth: 2,
        pointRadius: 7,
        pointHoverRadius: 9
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        r: {
          min: 0,
          max: 1.2,
          ticks: {
            stepSize: 0.2,
            font: { size: 11, family: 'DM Sans' },
            color: '#8FAAA0'
          },
          grid: {
            color: 'rgba(212, 230, 221, 0.6)'
          },
          pointLabels: {
            font: { size: 12, family: 'DM Sans', weight: '500' },
            color: '#2C4A40'
          }
        }
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: 'rgba(26, 60, 52, 0.95)',
          titleFont: { size: 13, family: 'DM Sans', weight: '600' },
          bodyFont: { size: 12, family: 'DM Sans' },
          padding: 12,
          borderColor: 'rgba(82, 183, 136, 0.3)',
          borderWidth: 1,
          callbacks: {
            label: function(context) {
              const cat = mainCats[context.dataIndex];
              const detail = d.categories.find(c => c.category === cat);
              return [
                `WAVG: ${context.parsed.r.toFixed(4)}`,
                detail ? `ランク: ${detail.rank}` : '',
                detail && detail.metabolites ? `主要変動: ${detail.metabolites.split('、').slice(0,2).join('、')}` : ''
              ].filter(Boolean);
            }
          }
        }
      }
    }
  });
}

