//  INIT
// ══════════════════════════════════════════════


function drawMetaboliteScatterMulti(allMeasurementData, catName){
  const canvas = document.getElementById('metabolite-scatter-chart');
  if(!canvas) return;
  
  if(metaboliteScatterChart) metaboliteScatterChart.destroy();
  
  // 散布図データセット（各測定ごと）
  const scatterDatasets = allMeasurementData.map((measurement, mIdx) => {
    const metData = measurement.metData.filter(m => m.weight > 0);
    const xPos = mIdx * 2;
    
    const points = metData.map(m => ({
      x: xPos,
      y: m.log2fc || 0,
      compound: m.compound,
      sample: m.sample,
      baseline: m.baseline,
      weight: m.weight
    }));
    
    const colors = points.map(p => {
      if(p.y > 0) return 'rgba(220, 53, 69, 0.8)';
      if(p.y < 0) return 'rgba(13, 110, 253, 0.8)';
      return 'rgba(108, 117, 125, 0.6)';
    });
    
    const radii = points.map(p => 5 + (p.weight || 0) * 2.5);
    
    return {
      type: 'scatter',
      label: measurement.date,
      data: points,
      backgroundColor: colors,
      borderColor: colors,
      borderWidth: 1,
      pointRadius: 2,
      pointHoverRadius: radii.map(r => r + 2),
      order: 1
    };
  });
  
  // 線データセット（同じ代謝物を繋ぐ）
  const lineDatasets = [];
  if(allMeasurementData.length > 1){
    // 1回目のデータから代謝物リストを取得
    const firstMets = allMeasurementData[0].metData.filter(m => m.weight > 0);
    
    firstMets.forEach(met => {
      const linePoints = allMeasurementData.map((measurement, mIdx) => {
        const found = measurement.metData.find(m => m.compound === met.compound);
        return {
          x: mIdx * 2,
          y: found ? (found.log2fc || 0) : null
        };
      }).filter(p => p.y !== null);
      
      if(linePoints.length > 1){
        lineDatasets.push({
          type: 'line',
          data: linePoints,
          borderColor: 'rgba(138, 170, 160, 0.3)',
          borderWidth: 1,
          pointRadius: 0,
          pointHoverRadius: 0,
          fill: false,
          tension: 0,
          order: 2
        });
      }
    });
  }
  
  const allDatasets = [...lineDatasets, ...scatterDatasets];
  
  console.log('患者パネル散布図データ:');
  console.log('scatterDatasets:', scatterDatasets);
  scatterDatasets.forEach((ds, idx) => {
    console.log(`  データセット${idx}: pointRadius =`, ds.pointRadius);
  });
  
  metaboliteScatterChart = new Chart(canvas, {
    type: 'scatter',
    data: { datasets: allDatasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        y: {
          title: {
            display: true,
            text: '基準値からの乖離度（🔴高い / 🔵低い）',
            font: { size: 13, family: 'DM Sans', weight: '600' },
            color: '#2C4A40'
          },
          min: -12,
          max: 12,
          ticks: {
            font: { size: 11, family: 'DM Sans' },
            color: '#5A7A6E'
          },
          grid: { 
            color: (ctx) => ctx.tick.value === 0 ? '#2C4A40' : 'rgba(212, 230, 221, 0.6)',
            lineWidth: (ctx) => ctx.tick.value === 0 ? 3 : 1
          }
        },
        x: {
          title: {
            display: allMeasurementData.length > 1,
            text: '測定回',
            font: { size: 11, family: 'DM Sans' },
            color: '#5A7A6E'
          },
          min: -0.5,
          max: Math.max(0.5, (allMeasurementData.length - 1) * 2 + 0.5),
          ticks: {
            callback: function(value) {
              const mIdx = Math.round(value / 2);
              if(mIdx >= 0 && mIdx < allMeasurementData.length) {
                return allMeasurementData[mIdx].date;
              }
              return '';
            },
            font: { size: 10, family: 'DM Sans' },
            color: '#8FAAA0'
          },
          grid: { display: false }
        }
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: 'rgba(26, 60, 52, 0.95)',
          titleFont: { size: 13, family: 'DM Sans', weight: '600' },
          bodyFont: { size: 12, family: 'DM Sans' },
          padding: 12,
          filter: function(item) {
            return item.dataset.type === 'scatter';
          },
          callbacks: {
            title: (ctx) => ctx[0].raw.compound,
            label: (ctx) => [
              `乖離度: ${ctx.raw.y.toFixed(3)} ${ctx.raw.y > 0 ? '高い' : '低い'}`,
              `実測値: ${ctx.raw.sample.toFixed(2)}`,
              `基準値: ${ctx.raw.baseline.toFixed(2)}`,
              `重要度: ${ctx.raw.weight.toFixed(1)}`
            ]
          }
        }
      }
    }
  });
}


function renderCategoryScatterGrid(pid, measurements){
  const grid = document.getElementById('category-scatter-grid');
  if(!grid) return;
  
  const allCategories = [
    'Energy currency / OXPHOS',
    'TCA Cycle',
    'Glycolysis',
    'Fatty acid metabolism',
    'Ketone body metabolism',
    'Lipid detail',
    'Amino acid / BCAA metabolism',
    'Redox balance / Glutathione',
    'Folate / Methionine–SAM cycle',
    'Urea Cycle',
    'Pentose Phosphate Pathway',
    'Purine metabolism',
    'Pyrimidine metabolism',
    'Polyamine metabolism',
    'Cofactors / Vitamin B',
    'Electrolyte / Minerals'
  ];
  
  grid.innerHTML = allCategories.map((cat, idx) => {
    const canvasId = `mini-scatter-${idx}`;
    const catData = measurements[selectedMeasurementIndex]?.categories.find(c => c.category === cat);
    const rank = catData?.rank || 'A';
    const [bg, fg] = rankBg(rank);
    
    return `
      <div style="background:${bg};border:1px solid ${fg};border-radius:10px;padding:10px;cursor:pointer"
           onclick="selectClinicCategory('${pid}','${cat.replace(/'/g,"\'")}')">
        <div style="font-size:10px;font-weight:600;color:${fg};margin-bottom:4px;display:flex;align-items:center;justify-content:space-between">
          <span>${CAT_JA[cat] || cat}</span>
          <span class="rank-badge ${rankColor(rank)}" style="width:18px;height:18px;font-size:10px;border-radius:4px">${rank}</span>
        </div>
        <div style="height:80px;position:relative">
          <canvas id="${canvasId}"></canvas>
        </div>
      </div>`;
  }).join('');
  
  // 各散布図と棒グラフを描画
  setTimeout(() => {
    allCategories.forEach((cat, idx) => {
      drawMiniScatter(pid, cat, measurements, `mini-scatter-${idx}`);
      drawMiniBar(pid, cat, measurements, `mini-scatter-${idx}-bar`);
    });
  }, 100);
}

const miniCharts = {};
function drawMiniScatter(pid, catName, measurements, canvasId){
  const canvas = document.getElementById(canvasId);
  if(!canvas) return;
  
  if(miniCharts[canvasId]) {
    miniCharts[canvasId].destroy();
  }
  
  const metData = METABOLITE_DATA?.[pid]?.[catName] || [];
  if(metData.length === 0) return;
  
  const filteredMets = metData.filter(m => m.weight > 0);
  if(filteredMets.length === 0) return;
  
  // 散布図データセット
  const scatterDatasets = measurements.map((m, mIdx) => {
    const xPos = mIdx * 1.5;
    
    const points = filteredMets.map(met => ({
      x: xPos,
      y: met.log2fc || 0,
      compound: met.compound
    }));
    
    const colors = points.map(p => {
      if(p.y > 0) return 'rgba(220, 53, 69, 0.9)';
      if(p.y < 0) return 'rgba(13, 110, 253, 0.9)';
      return 'rgba(108, 117, 125, 0.6)';
    });
    
    return {
      type: 'scatter',
      data: points,
      backgroundColor: colors,
      borderColor: colors,
      borderWidth: 0,
      pointRadius: 2.5,
      pointHoverRadius: 4.5,
      order: 1
    };
  });
  
  // 線データセット
  const lineDatasets = [];
  if(measurements.length > 1){
    filteredMets.forEach(met => {
      const linePoints = measurements.map((m, mIdx) => ({
        x: mIdx * 1.5,
        y: met.log2fc || 0
      }));
      
      lineDatasets.push({
        type: 'line',
        data: linePoints,
        borderColor: 'rgba(138, 170, 160, 0.25)',
        borderWidth: 0.5,
        pointRadius: 0,
        fill: false,
        tension: 0,
        order: 2
      });
    });
  }
  
  const allDatasets = [...lineDatasets, ...scatterDatasets];
  
  console.log('患者パネル散布図データ:');
  console.log('scatterDatasets:', scatterDatasets);
  scatterDatasets.forEach((ds, idx) => {
    console.log(`  データセット${idx}: pointRadius =`, ds.pointRadius);
  });
  
  miniCharts[canvasId] = new Chart(canvas, {
    type: 'scatter',
    data: { datasets: allDatasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        y: {
          display: true,
          min: -12,
          max: 12,
          ticks: { display: false },
          grid: { 
            color: (ctx) => ctx.tick.value === 0 ? 'rgba(0,0,0,0.6)' : 'rgba(0,0,0,0.08)',
            lineWidth: (ctx) => ctx.tick.value === 0 ? 2.5 : 0.5
          }
        },
        x: {
          display: false,
          min: -0.3,
          max: Math.max(0.3, (measurements.length - 1) * 1.5 + 0.3)
        }
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          enabled: true,
          backgroundColor: 'rgba(0,0,0,0.9)',
          titleFont: { size: 10, family: 'DM Sans' },
          bodyFont: { size: 9, family: 'DM Sans' },
          padding: 6,
          filter: function(item) {
            return item.dataset.type === 'scatter';
          },
          callbacks: {
            title: (ctx) => ctx[0].raw.compound,
            label: (ctx) => `乖離度: ${ctx.raw.y.toFixed(2)}`
          }
        }
      }
    }
  });
}


const miniBarCharts = {};
function drawMiniBar(pid, catName, measurements, canvasId){
  const canvas = document.getElementById(canvasId);
  if(!canvas) return;
  
  if(miniBarCharts[canvasId]) {
    miniBarCharts[canvasId].destroy();
  }
  
  // 各測定のWAVG値を取得
  const data = measurements.map((m, idx) => {
    const cat = m.categories.find(c => c.category === catName);
    return cat ? cat.wavg : 0;
  });
  
  // ランクに応じた色
  const colors = measurements.map((m, idx) => {
    const cat = m.categories.find(c => c.category === catName);
    if(!cat) return '#D4E6DD';
    const rank = cat.rank;
    if(rank === 'A') return '#2D6A4F';
    if(rank === 'B') return '#52B788';
    if(rank === 'C') return '#D4A017';
    if(rank === 'D') return '#D4600A';
    if(rank === 'E') return '#B03A2E';
    return '#D4E6DD';
  });
  
  miniBarCharts[canvasId] = new Chart(canvas, {
    type: 'bar',
    data: {
      labels: measurements.map((m, i) => (i+1) + '回目'),
      datasets: [{
        data: data,
        backgroundColor: colors,
        borderColor: colors.map(c => c),
        borderWidth: 1
      }]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        y: {
          display: false,
          min: 0,
          max: 1.2
        },
        x: {
          display: true,
          ticks: {
            display: measurements.length > 1,
            font: { size: 7 },
            color: 'rgba(0,0,0,0.5)'
          },
          grid: { display: false }
        }
      },
      plugins: {
        legend: { display: false },
        tooltip: { enabled: false }
      }
    }
  });
}


function renderCategoryButtons(pid, categories){
  const grid = document.getElementById('category-button-grid');
  if(!grid) return;
  
  const allCategories = [
    'Energy currency / OXPHOS',
    'TCA Cycle',
    'Glycolysis',
    'Fatty acid metabolism',
    'Ketone body metabolism',
    'Lipid detail',
    'Amino acid / BCAA metabolism',
    'Redox balance / Glutathione',
    'Folate / Methionine–SAM cycle',
    'Urea Cycle',
    'Pentose Phosphate Pathway',
    'Purine metabolism',
    'Pyrimidine metabolism',
    'Polyamine metabolism',
    'Cofactors / Vitamin B',
    'Electrolyte / Minerals'
  ];
  
  grid.innerHTML = allCategories.map(cat => {
    const catData = categories.find(c => c.category === cat);
    const rank = catData?.rank || 'A';
    const [bg, fg] = rankBg(rank);
    const catInfo = CATEGORY_INFO[cat] || {};
    const displayName = catInfo.ja_name || CAT_JA[cat] || cat;
    const description = catInfo.description || '';
    
    return `
      <button onclick="selectClinicCategory('${pid}','${cat.replace(/'/g,"\'")}');event.target.blur()" 
              title="${description}"
              style="background:${bg};border:2px solid ${fg};border-radius:8px;padding:10px;cursor:pointer;text-align:left;font-family:'DM Sans',sans-serif;transition:all .2s"
              onmouseover="this.style.transform='translateY(-2px)';this.style.boxShadow='var(--shadow-lg)'"
              onmouseout="this.style.transform='';this.style.boxShadow=''">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:4px">
          <span style="font-size:11px;font-weight:600;color:${fg};line-height:1.3">${displayName}</span>
          <span class="rank-badge ${rankColor(rank)}" style="width:20px;height:20px;font-size:11px;border-radius:5px">${rank}</span>
        </div>
      </button>`;
  }).join('');
}

function renderMetaboliteTable(mets){
  return `
    <table class="score-table">
      <thead><tr>
        <th>代謝物</th>
        <th>重要度</th>
        <th>実測値</th>
        <th>基準値</th>
        <th>乖離度</th>
        <th>前回比</th>
      </tr></thead>
      <tbody>
        ${mets.map(m => {
          const weightBadge = m.weight > 2 ? 'background:#2D6A4F;color:#fff' : m.weight > 1 ? 'background:#95D5B2;color:#1A3C34' : 'background:#D4E6DD;color:#5A7A6E';
          
          // 前回比の計算（複数測定がある場合）
          let changeHtml = '<td>—</td>';
          if(m.previousLog2FC !== undefined && m.previousLog2FC !== null){
            const change = m.log2fc - m.previousLog2FC;
            const arrow = change > 0.1 ? '↑' : change < -0.1 ? '↓' : '→';
            const color = change > 0.1 ? '#B03A2E' : change < -0.1 ? '#2E7D32' : 'var(--ink4)';
            changeHtml = `<td style="color:${color};font-weight:600">${arrow} ${change.toFixed(2)}</td>`;
          }
          
          return `
          <tr>
            <td><strong>${m.compound}</strong></td>
            <td><span style="padding:2px 8px;border-radius:12px;font-size:11px;font-weight:600;${weightBadge}">${m.weight.toFixed(1)}</span></td>
            <td>${m.sample.toFixed(2)}</td>
            <td>${m.baseline.toFixed(2)}</td>
            <td style="font-family:'JetBrains Mono',monospace">${m.log2fc.toFixed(3)}</td>
            ${changeHtml}
          </tr>`;
        }).join('')}
      </tbody>
    </table>`;
}

function renderMetaboliteTableMulti(mets, measurements){
  // ヘッダー行を生成
  const headers = ['代謝物', '重要度', '基準値'];
  measurements.forEach(m => {
    headers.push(`実測値 (${m.date})`);
  });
  if(measurements.length > 1){
    headers.push('前回比');
  }
  
  const headerHtml = headers.map(h => `<th>${h}</th>`).join('');
  
  // データ行を生成
  const rowsHtml = mets.map(m => {
    const weightBadge = m.weight > 2 ? 'background:#2D6A4F;color:#fff' : m.weight > 1 ? 'background:#95D5B2;color:#1A3C34' : 'background:#D4E6DD;color:#5A7A6E';
    
    let cells = `
      <td><strong>${m.compound}</strong></td>
      <td><span style="padding:2px 8px;border-radius:12px;font-size:11px;font-weight:600;${weightBadge}">${m.weight.toFixed(1)}</span></td>
      <td>${m.baseline.toFixed(2)}</td>
      <td>${m.sample.toFixed(2)}</td>`;
    
    // 複数測定の場合、各測定値を追加
    if(measurements.length > 1){
      // 2回目以降の測定値（現在のデータには1回目しかないのでダミー）
      for(let i = 1; i < measurements.length; i++){
        cells += `<td>—</td>`;
      }
      
      // 前回比
      cells += `<td>—</td>`;
    }
    
    return `<tr>${cells}</tr>`;
  }).join('');
  
  return `
    <table class="score-table">
      <thead><tr>${headerHtml}</tr></thead>
      <tbody>${rowsHtml}</tbody>
    </table>`;
}


function sortMetabolites(pid, catName, sortType){
  const metData = METABOLITE_DATA?.[pid]?.[catName] || [];
  if(metData.length === 0) return;
  
  let sorted = [...metData];
  switch(sortType){
    case 'weight':
      sorted.sort((a,b) => {
        const scoreA = (a.weight || 0) * Math.abs(a.log2fc || 0);
        const scoreB = (b.weight || 0) * Math.abs(b.log2fc || 0);
        return scoreB - scoreA;
      });
      break;
    case 'abs_log2fc':
      sorted.sort((a,b) => Math.abs(b.log2fc) - Math.abs(a.log2fc));
      break;
    case 'log2fc_asc':
      sorted.sort((a,b) => a.log2fc - b.log2fc);
      break;
    case 'log2fc_desc':
      sorted.sort((a,b) => b.log2fc - a.log2fc);
      break;
  }
  
  const container = document.getElementById('metabolite-table-container');
  if(container){
    container.innerHTML = renderMetaboliteTable(sorted);
  }
}


