function selectPatientMode() {
  const pid = document.getElementById('patient-login-id').value.trim();
  if(!pid) {
    alert('患者IDを入力してください');
    return;
  }
  
  const patient = PATIENT_DATA[pid];
  if(!patient) {
    alert('患者IDが見つかりません');
    return;
  }
  
  currentMode = 'patient';
  currentPatientId = pid;
  
  document.getElementById('login-screen').style.display = 'none';
  document.getElementById('patient-screen').style.display = 'block';
  
  renderPatientScreen(pid);
}

function renderPatientScreen(pid) {
  const patient = PATIENT_DATA[pid];
  const container = document.getElementById('patient-main');
  if(!container) return;
  
  // 患者情報ヘッダー
  const headerHtml = `
    <div style="background:var(--sage);padding:20px;margin-bottom:20px;border-radius:8px">
      <h2 style="margin:0;color:var(--forest)">👤 マイページ</h2>
      <p style="margin:8px 0 0 0;color:var(--ink3)">患者ID: ${pid}</p>
    </div>
  `;
  
  // カテゴリ一覧
  const categories = patient.categories || [];
  const categoryHtml = `
    <div style="margin-bottom:20px">
      <h3 style="color:var(--forest)">📊 検査結果カテゴリ</h3>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;margin-top:12px">
        ${categories.map(cat => {
          const [bg, fg] = rankBg(cat.rank);
          return `
            <button onclick="selectPatientCategory('${pid}','${cat.category.replace(/'/g,"\\'")}')" 
                    style="background:${bg};border:2px solid ${fg};border-radius:8px;padding:12px;cursor:pointer;text-align:left;transition:all .2s"
                    onmouseover="this.style.transform='translateY(-2px)'"
                    onmouseout="this.style.transform=''">
              <div style="display:flex;align-items:center;justify-content:space-between">
                <span style="font-size:12px;font-weight:600;color:${fg}">${CATEGORY_INFO[cat.category]?.ja_name || CAT_JA[cat.category] || cat.category}</span>
                <span class="rank-badge ${rankColor(cat.rank)}" style="width:24px;height:24px;font-size:12px">${cat.rank}</span>
              </div>
            </button>`;
        }).join('')}
      </div>
    </div>
  `;
  
  container.innerHTML = headerHtml + categoryHtml + `
    <div id="patient-category-detail" style="margin-top:20px"></div>
  `;
}

function selectPatientCategory(pid, catName) {
  const patient = PATIENT_DATA[pid];
  const cat = patient.categories.find(c => c.category === catName);
  if(!cat) return;
  
  const detailEl = document.getElementById('patient-category-detail');
  if(!detailEl) return;
  
  const mets = parseMetabolites(cat.metabolites);
  const metHtml = mets.map(m=>{
    const desc = METABOLITE_DESCRIPTIONS ? (METABOLITE_DESCRIPTIONS[m.name] || '') : '';
    const arrow = m.dir==='down'?'↓':m.dir==='up'?'↑':'';
    return `<span class="metabolite-tag ${m.dir}" title="${desc}" style="cursor:${desc?'help':'default'};${desc?'border-bottom:1px dotted #666':''}">${m.name}${arrow}</span>`;
  }).join('');
  
  detailEl.innerHTML = `
    <div style="background:white;border-radius:12px;padding:20px;box-shadow:var(--shadow)">
      <h3 style="color:var(--forest);margin-top:0">${CATEGORY_INFO[catName]?.ja_name || CAT_JA[catName] || catName}</h3>
      
      <div style="margin-bottom:20px;background:var(--foam);padding:12px;border-radius:8px">
        <div style="font-size:11px;color:var(--ink3);margin-bottom:6px">主要な変動</div>
        <div class="metabolite-list">${metHtml}</div>
      </div>
      
      <div class="detail-tabs" style="margin-bottom:16px">
        <div class="detail-tab active" onclick="switchPatientTab('metabolites',this,'${pid}','${catName.replace(/'/g,"\'")}')">🧪 個別代謝物</div>
        <div class="detail-tab" onclick="switchPatientTab('patient',this,'${pid}','${catName.replace(/'/g,"\'")}')">💬 生活で気をつけること</div>
      </div>
      
      <div id="patient-tab-body"></div>
    </div>
  `;
  
  // デフォルトで個別代謝物タブを表示
  setTimeout(() => {
    const firstTab = document.querySelector('.detail-tab');
    if(firstTab) switchPatientTab('metabolites', firstTab, pid, catName);
  }, 50);
}

function switchPatientTab(tab, el, pid, catName) {
  document.querySelectorAll('.detail-tab').forEach(t => t.classList.remove('active'));
  el.classList.add('active');
  
  const patient = PATIENT_DATA[pid];
  const cat = patient.categories.find(c => c.category === catName);
  if(!cat) return;
  
  const body = document.getElementById('patient-tab-body');
  if(!body) return;
  
  if(tab === 'metabolites') {
    // 個別代謝物タブ（クリニック版と同じ）
    const measurements = patient.measurements || [{date: patient.date, categories: patient.categories}];
    const allMeasurementData = measurements.map((m, mIdx) => {
      const catData = m.categories.find(c => c.category === catName);
      const metData = METABOLITE_DATA?.[pid]?.[catName] || [];
      return { date: m.date, index: mIdx, metData: metData };
    });
    
    const latestMetData = allMeasurementData[0]?.metData || [];
    
    if(latestMetData.length === 0) {
      body.innerHTML = '<p style="text-align:center;color:var(--ink4);padding:40px">このカテゴリの詳細データがありません</p>';
      return;
    }
    
    const sortedMets = [...latestMetData].sort((a,b) => {
      const scoreA = (a.weight || 0) * Math.abs(a.log2fc || 0);
      const scoreB = (b.weight || 0) * Math.abs(b.log2fc || 0);
      return scoreB - scoreA;
    });
    
    body.innerHTML = `
      <div style="height:400px;position:relative;margin-bottom:16px">
        <canvas id="patient-metabolite-chart"></canvas>
      </div>
      <div style="max-height:400px;overflow-y:auto">
        ${renderMetaboliteTableMulti(sortedMets, measurements)}
      </div>
    `;
    
    setTimeout(() => drawMetaboliteScatterMulti(allMeasurementData, catName, 'patient-metabolite-chart'), 50);
    
  } else if(tab === 'patient') {
    // 患者向けコメントタブ
    body.innerHTML = `
      <div style="overflow-x:auto">
        <table class="score-table" style="table-layout:fixed;width:100%">
          <thead>
            <tr>
              <th style="width:30%">変動について</th>
              <th style="width:70%">生活で気をつけること</th>
            </tr>
          </thead>
          <tbody>
            ${(cat.metabolite_insights || []).map(insight => `
              <tr style="vertical-align:top">
                <td style="padding:12px;line-height:1.6;background:rgba(33,150,243,0.05)">
                  ${insight.movement}
                </td>
                <td style="padding:12px;line-height:1.6;background:rgba(46,125,50,0.05)">
                  ${insight.patient_comment}
                </td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;
  }
}







// ═══════════════════════════════════════════════════════════════
//  患者パネル用散布図（Chart.js版・クリニック側と同じデザイン）
// ═══════════════════════════════════════════════════════════════
let patientMetaboliteScatterChart = null;

function drawMetaboliteScatterMultiCanvas(allMeasurementData, catName, canvasId) {
  const canvas = document.getElementById(canvasId || 'patient-metabolite-scatter');
  if(!canvas) {
    console.error('Canvas not found:', canvasId);
    return;
  }
  
  if(patientMetaboliteScatterChart) {
    patientMetaboliteScatterChart.destroy();
  }
  
  // 散布図データセット（各測定ごと）
  const scatterDatasets = allMeasurementData.map((measurement, mIdx) => {
    const metData = measurement.metData.filter(m => m.weight > 0);
    const xPos = mIdx * 2;
    
    const points = metData.map(m => ({
      x: xPos,
      y: m.log2fc || 0,
      compound: m.compound,
      sample: m.sample,
      baseline: m.baseline,
      weight: m.weight
    }));
    
    const colors = points.map(p => {
      if(p.y > 0) return 'rgba(220, 53, 69, 0.8)';
      if(p.y < 0) return 'rgba(13, 110, 253, 0.8)';
      return 'rgba(108, 117, 125, 0.6)';
    });
    
    const radii = points.map(p => 5 + (p.weight || 0) * 2.5);
    
    return {
      type: 'scatter',
      label: measurement.date,
      data: points,
      backgroundColor: colors,
      borderColor: colors,
      borderWidth: 1,
      pointRadius: radii,
      pointHoverRadius: radii.map(r => r + 2),
      order: 1
    };
  });
  
  // 線データセット（同じ代謝物を繋ぐ）
  const lineDatasets = [];
  if(allMeasurementData.length > 1){
    const firstMets = allMeasurementData[0].metData.filter(m => m.weight > 0);
    
    firstMets.forEach(met => {
      const linePoints = allMeasurementData.map((measurement, mIdx) => {
        const found = measurement.metData.find(m => m.compound === met.compound);
        return {
          x: mIdx * 2,
          y: found ? (found.log2fc || 0) : null
        };
      }).filter(p => p.y !== null);
      
      if(linePoints.length > 1){
        lineDatasets.push({
          type: 'line',
          data: linePoints,
          borderColor: 'rgba(138, 170, 160, 0.3)',
          borderWidth: 1,
          pointRadius: 0,
          pointHoverRadius: 0,
          fill: false,
          tension: 0,
          order: 2
        });
      }
    });
  }
  
  const allDatasets = [...lineDatasets, ...scatterDatasets];
  
  console.log('患者パネル散布図データ:');
  console.log('scatterDatasets:', scatterDatasets);
  scatterDatasets.forEach((ds, idx) => {
    console.log(`  データセット${idx}: pointRadius =`, ds.pointRadius);
  });
  
  patientMetaboliteScatterChart = new Chart(canvas, {
    type: 'scatter',
    data: { datasets: allDatasets },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        y: {
          title: {
            display: true,
            text: '基準値からの乖離度（🔴高い / 🔵低い）',
            font: { size: 13, family: 'DM Sans', weight: '600' },
            color: '#2C4A40'
          },
          min: -12,
          max: 12,
          ticks: {
            font: { size: 11, family: 'DM Sans' },
            color: '#5A7A6E'
          },
          grid: { 
            color: (ctx) => ctx.tick.value === 0 ? '#2C4A40' : 'rgba(212, 230, 221, 0.6)',
            lineWidth: (ctx) => ctx.tick.value === 0 ? 3 : 1
          }
        },
        x: {
          title: {
            display: allMeasurementData.length > 1,
            text: '測定回',
            font: { size: 11, family: 'DM Sans' },
            color: '#5A7A6E'
          },
          min: -0.5,
          max: Math.max(0.5, (allMeasurementData.length - 1) * 2 + 0.5),
          ticks: {
            callback: function(value) {
              const mIdx = Math.round(value / 2);
              if(mIdx >= 0 && mIdx < allMeasurementData.length) {
                return allMeasurementData[mIdx].date;
              }
              return '';
            },
            font: { size: 10, family: 'DM Sans' },
            color: '#8FAAA0'
          },
          grid: { display: false }
        }
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: 'rgba(26, 60, 52, 0.95)',
          titleFont: { size: 13, family: 'DM Sans', weight: '600' },
          bodyFont: { size: 12, family: 'DM Sans' },
          padding: 12,
          filter: function(item) {
            return item.dataset.type === 'scatter';
          },
          callbacks: {
            title: (ctx) => ctx[0].raw.compound,
            label: (ctx) => [
              `乖離度: ${ctx.raw.y.toFixed(3)} ${ctx.raw.y > 0 ? '高い' : '低い'}`,
              `実測値: ${ctx.raw.sample.toFixed(2)}`,
              `基準値: ${ctx.raw.baseline.toFixed(2)}`,
              `重要度: ${ctx.raw.weight.toFixed(1)}`
            ]
          }
        }
      }
    }
  });
}


